package report

import (
	"fmt"
	"io"
	"strconv"
	"strings"

	"github.com/moveeeax/ebs-gp3-audit/internal/audit"
)

// candidates returns the findings a migration plan should act on.
func candidates(r audit.Report) []audit.Finding {
	var out []audit.Finding
	for _, f := range r.Findings {
		if f.Candidate && f.Gp3IOPS > 0 {
			out = append(out, f)
		}
	}
	return out
}

// shellQuote single-quotes s for a POSIX shell.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

const scriptHeader = `#!/usr/bin/env bash
# gp3 migration plan generated by ebs-gp3-audit %s.
# %d volume(s), estimated saving $%.2f/mo.
#
# Each command moves one volume to gp3 with the IOPS and throughput the audit
# priced, and a larger size where gp3 needs one for the IOPS, so the
# migration does not lower performance.
#
# The script runs every command with --dry-run unless APPLY=1 is set: AWS then
# checks permissions and parameters without changing anything. Review the
# plan, then run it again with APPLY=1.
#
# EBS limits (https://docs.aws.amazon.com/ebs/latest/userguide/ebs-modify-volume.html):
#   - a volume can be modified up to 4 times in a rolling 24-hour period, and
#     a new modification waits until the previous one is "completed";
#   - a modification cannot be cancelled, and a volume cannot shrink.
# Applying needs ec2:ModifyVolume; ebs-gp3-audit itself stays read-only.
set -euo pipefail

modify() {
  if [ "${APPLY:-0}" = "1" ]; then
    aws ec2 modify-volume "$@"
    return
  fi
  local out
  if out=$(aws ec2 modify-volume --dry-run "$@" 2>&1); then
    return 0
  fi
  case "$out" in
    *DryRunOperation*) echo "dry-run ok: $*" ;;
    *) echo "$out" >&2; return 1 ;;
  esac
}
`

// PlanScript writes a bash script with one aws ec2 modify-volume call per
// candidate, using the gp3 configuration from the cost model.
func PlanScript(w io.Writer, r audit.Report, version string) error {
	cs := candidates(r)
	var b strings.Builder
	fmt.Fprintf(&b, scriptHeader, version, len(cs), totalSaving(cs))
	if len(cs) == 0 {
		b.WriteString("\n# No gp3 migration candidates.\n")
	}
	for _, f := range cs {
		fmt.Fprintf(&b, "\n# %s (%s, %d GiB): save $%.2f/mo\n", f.VolumeID, f.Type, f.SizeGiB, f.MonthlySaving)
		b.WriteString("modify")
		if f.Region != "" {
			b.WriteString(" --region " + shellQuote(f.Region))
		}
		fmt.Fprintf(&b, " --volume-id %s --volume-type gp3", shellQuote(f.VolumeID))
		if f.Gp3SizeGiB > f.SizeGiB {
			fmt.Fprintf(&b, " --size %d", f.Gp3SizeGiB)
		}
		fmt.Fprintf(&b, " --iops %d --throughput %d\n", f.Gp3IOPS, f.Gp3Throughput)
	}
	_, err := io.WriteString(w, b.String())
	return err
}

// hclQuote quotes s as an HCL string literal, escaping template sequences.
func hclQuote(s string) string {
	q := strconv.Quote(s)
	q = strings.ReplaceAll(q, "${", "$${")
	return strings.ReplaceAll(q, "%{", "%%{")
}

// PlanTerraform writes a Terraform locals map, keyed by volume ID, with the
// gp3 attributes to set on each candidate.
func PlanTerraform(w io.Writer, r audit.Report, version string) error {
	cs := candidates(r)
	var b strings.Builder
	fmt.Fprintf(&b, "# gp3 migration plan generated by ebs-gp3-audit %s.\n", version)
	fmt.Fprintf(&b, "# %d volume(s), estimated saving $%.2f/mo.\n", len(cs), totalSaving(cs))
	b.WriteString("#\n")
	b.WriteString("# Attribute suggestions keyed by volume ID. The names match aws_instance\n")
	b.WriteString("# root_block_device / ebs_block_device; on aws_ebs_volume use type and size\n")
	b.WriteString("# instead of volume_type and volume_size.\n")
	b.WriteString("locals {\n")
	if len(cs) == 0 {
		b.WriteString("  ebs_gp3_migration = {}\n")
	} else {
		b.WriteString("  ebs_gp3_migration = {\n")
		for _, f := range cs {
			fmt.Fprintf(&b, "    # %s, %d GiB: save $%.2f/mo\n", f.Type, f.SizeGiB, f.MonthlySaving)
			fmt.Fprintf(&b, "    %s = {\n", hclQuote(f.VolumeID))
			b.WriteString("      volume_type = \"gp3\"\n")
			fmt.Fprintf(&b, "      volume_size = %d\n", f.Gp3SizeGiB)
			fmt.Fprintf(&b, "      iops        = %d\n", f.Gp3IOPS)
			fmt.Fprintf(&b, "      throughput  = %d\n", f.Gp3Throughput)
			b.WriteString("    }\n")
		}
		b.WriteString("  }\n")
	}
	b.WriteString("}\n")
	_, err := io.WriteString(w, b.String())
	return err
}

func totalSaving(cs []audit.Finding) float64 {
	var t float64
	for _, f := range cs {
		t += f.MonthlySaving
	}
	return t
}
